	/** Returns the screen position of a sub-tile position, with sub-pixel precision, in a new pf. */
	private static pf projectToScreen(float subx, float suby, Polygon poly)
	{
		return projectToScreen(subx, suby, poly, pf(0, 0));
	}

	/** Puts the screen position of a sub-tile position in out, with sub-pixel precision, and returns out. */
	private static pf projectToScreen(float subx, float suby, Polygon poly, pf out)
	{
		int[] xs = poly.xpoints;
		int[] ys = poly.ypoints;
		if (subx + suby <= 1)
		{
			out.setLocation(
				xs[0] + (xs[1] - xs[0]) * subx + (xs[3] - xs[0]) * suby,
				ys[0] + (ys[1] - ys[0]) * subx + (ys[3] - ys[0]) * suby);
			return out;
		}
		subx = 1 - subx;
		suby = 1 - suby;
		out.setLocation(
			xs[2] + (xs[3] - xs[2]) * subx + (xs[1] - xs[2]) * suby,
			ys[2] + (ys[3] - ys[2]) * subx + (ys[1] - ys[2]) * suby);
		return out;
	}

	private pf getBarycentre(int mx, int my, int x0, int y0, int x1, int y1, int x2, int y2, int x3, int y3)
	{
		// Try the triangle made by corners 0, 1, 3 first, then the one made by corners 1, 2, 3.
		float
			area13p = triangleArea(x1, y1, x3, y3, mx, my),
			area03p = triangleArea(x0, y0, x3, y3, mx, my),
			area01p = triangleArea(x0, y0, x1, y1, mx, my),
			area013 = triangleArea(x0, y0, x1, y1, x3, y3);
		float
			swb0 = area13p / area013,
			swb1 = area03p / area013,
			swb3 = area01p / area013;
		if (swb0 + swb1 + swb3 > 1f)
		{
			float
				area23p = triangleArea(x2, y2, x3, y3, mx, my),
				area12p = triangleArea(x1, y1, x2, y2, mx, my),
				area123 = triangleArea(x1, y1, x2, y2, x3, y3);
			return pf(1 - area12p / area123, 1 - area23p / area123);
		}
		return pf(swb1, swb3);
	}

	@Subscribe public void onGameStateChanged(GameStateChanged e) {
		// The scene base is final only after the scene loads.
		if (e.getGameState() != GameState.LOGGED_IN) return;

		WorldView worldView = client.getTopLevelWorldView();
		// Keep the same regions that drawing reads, so drawing does not read a region from the config again.
		if (worldView != null) loadStrokes(sceneRegions(worldView));
	}

	// How many regions around the scene and its extended border also load and draw their strokes.
	// One region lets a stroke that starts just outside the scene still show.
	private static final int NEARBY_REGIONS = 1;

	Map<Integer, List<Stroke>> strokesByRegion = new HashMap<>();

	/** Loads the strokes of the regions, and unloads the strokes of all other regions. */
	void loadStrokes(int[] regions) {
		Set<Integer> loadedRegions = strokesByRegion.keySet();
		Set<Integer> keptRegions = new HashSet<>();
		for (int region : regions)
		{
			keptRegions.add(region);
		}
		List<Integer> regionsToUnload = new ArrayList<>(loadedRegions);
		regionsToUnload.removeAll(keptRegions);
		for (Integer region : regionsToUnload)
		{
			strokesByRegion.remove(region);
		}
		List<Integer> regionsToLoad = new ArrayList<>(keptRegions);
		// Keep the regions that are loaded already, so undo, redo and the party sync keep the same Stroke objects.
		regionsToLoad.removeAll(loadedRegions);
		for (Integer region : regionsToLoad)
		{
			strokesByRegion.put(region, readStrokes(region));
		}
	}

	/** Returns the strokes of the region. If the region is not loaded, loads it from the config first. */
	List<Stroke> regionStrokes(int regionId) {
		return strokesByRegion.computeIfAbsent(regionId, this::readStrokes);
	}

	// Regions whose saved strokes cannot be read, for example because a newer version of the plugin saved them.
	// These regions are not saved, so the saved strokes stay for the version that can read them.
	private final Set<Integer> unreadableRegions = new HashSet<>();

	private List<Stroke> readStrokes(int regionId) {
		String key = "strokes_" + regionId;
		String conf = configManager.getConfiguration(RsPaintConfig.GROUP, key);
		unreadableRegions.remove(regionId);
		if (conf == null) return new ArrayList<>();

		StrokeStorage.Loaded loaded;
		try
		{
			loaded = storage.read(conf);
		}
		catch (StrokeStorage.UnreadableStrokesException e)
		{
			log.warn("Cannot load the strokes of region {}: {}", regionId, e.getMessage());
			unreadableRegions.add(regionId);
			return new ArrayList<>();
		}

		List<Stroke> strokes = new ArrayList<>();
		for (PartyCanvasSync.SyncedStroke synced : loaded.getStrokes())
		{
			Stroke stroke = PartyCanvasSync.fromSynced(synced);
			clock.advancePast(stroke.order);
			strokes.add(stroke);
		}
		if (loaded.getVersion() < StrokeStorage.FORMAT_VERSION)
		{
			migrate(key, loaded, conf);
		}
		if (!strokes.isEmpty())
		{
			// Party members get the strokes of the area that the player is in. They already have the other strokes,
			// so only the strokes of this region go out.
			partySync.onStrokesRestored(strokes);
		}
		return strokes;
	}

	// The old text of each config key that is being backed up now, so a region that loads again does not back up twice.
	private final Map<String, String> backupsInProgress = new HashMap<>();

	/**
	 * Saves the old text to a backup file, then saves the strokes again in the current format, so the old format is
	 * read only once. The file is written on a background thread. If the file cannot be written, the old text stays
	 * saved until the player changes the strokes of the region, and the next load tries the backup again.
	 */
	private void migrate(String key, StrokeStorage.Loaded loaded, String oldText)
	{
		if (oldText.equals(backupsInProgress.get(key)))
		{
			return;
		}
		backupsInProgress.put(key, oldText);
		String newText = storage.write(loaded.getStrokes());
		backups.save(key, loaded.getVersion(), oldText).whenComplete((ignored, error) -> clientThread.invoke(() ->
		{
			backupsInProgress.remove(key, oldText);
			if (error != null)
			{
				log.warn("Cannot save a backup of {}, so it stays in the old format", key, error);
				return;
			}
			// A new save, or a profile change, can replace the old text first. Do not save over that text.
			if (oldText.equals(configManager.getConfiguration(RsPaintConfig.GROUP, key)))
			{
				configManager.setConfiguration(RsPaintConfig.GROUP, key, newText);
			}
		}));
	}

	void saveStrokes(int regionId) {
		List<Stroke> strokes = strokesByRegion.get(regionId);
		if (strokes == null || unreadableRegions.contains(regionId)) return;
		List<PartyCanvasSync.SyncedStroke> synced = new ArrayList<>();
		for (Stroke stroke : strokes)
		{
			if (!stroke.pts.isEmpty())
			{
				synced.add(PartyCanvasSync.toSynced(stroke, stroke.pts));
			}
		}
		configManager.setConfiguration(RsPaintConfig.GROUP, "strokes_" + regionId, storage.write(synced));
	}

	/**
	 * Deletes the local player's strokes in the loaded regions, the area around the player, and tells party members.
	 * Strokes in other regions stay saved.
	 */
	public void clearCanvas()
	{
		currentStroke = null;
		skippedPoint = null;
		for (Map.Entry<Integer, List<Stroke>> entry : strokesByRegion.entrySet())
		{
			if (!entry.getValue().isEmpty())
			{
				entry.getValue().clear();
				saveStrokes(entry.getKey());
			}
		}
		// A reset cannot be undone, so the history goes too.
		undoStack.clear();
		redoStack.clear();
		currentErase = null;
		partySync.onCanvasCleared();
	}

	/** Returns a copy of the local player's loaded strokes. Client thread only. */
	List<PartyCanvasSync.SyncedStroke> ownStrokes()
	{
		List<PartyCanvasSync.SyncedStroke> result = new ArrayList<>();
		for (List<Stroke> strokes : strokesByRegion.values())
		{
			for (Stroke stroke : strokes)
			{
				if (!stroke.pts.isEmpty())
				{
					result.add(PartyCanvasSync.toSynced(stroke, stroke.pts));
				}
			}
		}
		return result;
	}

	/**
	 * Adds the strokes to the local player's canvas with new ids, saves them, and sends them to the party. Client thread only.
	 * The strokes draw over all existing strokes, in the order of the list.
	 */
	void importStrokes(List<PartyCanvasSync.SyncedStroke> strokes)
	{
		Set<Integer> changedRegions = new LinkedHashSet<>();
		List<Stroke> imported = new ArrayList<>();
		for (PartyCanvasSync.SyncedStroke synced : strokes)
		{
			if (synced.getPoints() == null || synced.getPoints().isEmpty())
			{
				continue;
			}
			Stroke stroke = new Stroke();
			stroke.color = new Color(synced.getColor(), true);
			stroke.strokeWidth = synced.getStrokeWidth();
			stroke.order = clock.next();
			stroke.plane = synced.getPlane();
			stroke.pts.addAll(StrokeCodec.simplify(synced.getPoints()));
			regionStrokes(stroke.primaryRegion()).add(stroke);
			changedRegions.add(stroke.primaryRegion());
			imported.add(stroke);
		}
		changedRegions.forEach(this::saveStrokes);
		partySync.onStrokesRestored(imported);
	}

	private void drawStrokes(Graphics2D graphics, int mx, int my)
	{
		WorldView worldView = client.getTopLevelWorldView();
		int[] regions = sceneRegions(worldView);
		if (regions.length == 0)
		{
			return;
		}

		// Turn on antialiasing and transparency only for the strokes, and restore the old state, so the toolbar stays sharp.
		Object oldAntialiasing = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		Object oldStrokeControl = graphics.getRenderingHint(RenderingHints.KEY_STROKE_CONTROL);
		java.awt.Stroke oldStroke = graphics.getStroke();
		Composite oldComposite = graphics.getComposite();
		try
		{
			// Each stroke is one path that is drawn one time, so the parts of a stroke that cross do not get darker.
			// Each new stroke is drawn over the older strokes, so the colors of different strokes mix.
			// This is true for the opacity of the stroke color and for the opacity of all strokes.
			renderDistance = Math.max(0, config.renderDistance());
			cameraTileX = (int) Math.floor(client.getCameraFpX() / Perspective.LOCAL_TILE_SIZE);
			cameraTileY = (int) Math.floor(client.getCameraFpY() / Perspective.LOCAL_TILE_SIZE);
			transparentStrokes = config.transparentStrokes();
			if (transparentStrokes)
			{
				float opacity = Math.max(0f, Math.min(1f, config.strokeOpacity() / 100f));
				graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, opacity));
			}
			if (config.antialiasing())
			{
				graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				// Keep the float positions. The default moves line ends to pixel centers.
				graphics.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			}
			else
			{
				graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
			}
			drawStrokes(graphics, worldView, regions, mx, my, config.lineStyle());
		}
		finally
		{
			if (oldAntialiasing != null)
			{
				graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, oldAntialiasing);
			}
			if (oldStrokeControl != null)
			{
				graphics.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, oldStrokeControl);
			}
			graphics.setStroke(oldStroke);
			graphics.setComposite(oldComposite);
		}
	}

	// The ids of the regions in the scene, and the scene base, size and extended border they are for.
	// Made again only when the scene moves or the border changes, so drawing does not make a new array on each frame.
	private int[] sceneRegions = new int[0];
	private int sceneRegionsBaseX, sceneRegionsBaseY, sceneRegionsSizeX, sceneRegionsSizeY, sceneRegionsBorder;

	/**
	 * Returns the ids of all regions that have tiles in the scene, and of the NEARBY_REGIONS regions
	 * around them. Do not change the array.
	 * A stroke is stored under the region of the world tile of its first point. The nearby regions let a stroke that
	 * starts outside the scene and goes into it still show. Its points outside the scene do not draw.
	 * Inside an instance, the region of a stroke is a region of the instance
	 * coordinates, but getMapRegions() gives the template regions. So the ids come from the scene base and size.
	 * Outside an instance, they are the same regions as getMapRegions() gives.
	 * loadStrokes keeps these regions in memory when the scene loads.
	 */
	private int[] sceneRegions(WorldView worldView)
	{
		int baseX = worldView.getBaseX();
		int baseY = worldView.getBaseY();
		int sizeX = worldView.getSizeX();
		int sizeY = worldView.getSizeY();
		int margin = NEARBY_REGIONS;
		// Strokes also draw on the extended scene past the loading line, so its regions are in the list too.
		int border = loadedBorder(worldView);
		if (baseX == sceneRegionsBaseX && baseY == sceneRegionsBaseY && sizeX == sceneRegionsSizeX && sizeY == sceneRegionsSizeY
			&& border == sceneRegionsBorder)
		{
			return sceneRegions;
		}
		sceneRegionsBaseX = baseX;
		sceneRegionsBaseY = baseY;
		sceneRegionsSizeX = sizeX;
		sceneRegionsSizeY = sizeY;
		sceneRegionsBorder = border;

		if (sizeX <= 0 || sizeY <= 0)
		{
			sceneRegions = new int[0];
			return sceneRegions;
		}
		// The same formula as WorldPoint.getRegionID(). A region is 64 by 64 tiles, and a region x or y is 0 to 255.
		int minRegionX = Math.max(0, ((baseX - border) >> 6) - margin);
		int maxRegionX = Math.min(0xFF, ((baseX + sizeX + border - 1) >> 6) + margin);
		int minRegionY = Math.max(0, ((baseY - border) >> 6) - margin);
		int maxRegionY = Math.min(0xFF, ((baseY + sizeY + border - 1) >> 6) + margin);
		int[] regions = new int[(maxRegionX - minRegionX + 1) * (maxRegionY - minRegionY + 1)];
		int i = 0;
		for (int regionX = minRegionX; regionX <= maxRegionX; regionX++)
		{
			for (int regionY = minRegionY; regionY <= maxRegionY; regionY++)
			{
				regions[i++] = regionX << 8 | regionY;
			}
		}
		sceneRegions = regions;
		return regions;
	}

	// The strokes to draw in this frame. Reused, so drawing does not make a new list on each frame.
	private final List<Stroke> visibleStrokes = new ArrayList<>();
	// A frame draws at most this many points. If the shown strokes have more, the oldest strokes do not draw.
	// Each party member keeps at most 100,000 points, but a big party can have more in all. This keeps the frame time bounded.
	private static final int MAX_DRAWN_POINTS = 200_000;

	private void drawStrokes(Graphics2D graphics, WorldView worldView, int[] regions, int mx, int my, LineStyle style)
	{
		if (erasing)
		{
			eraseOwnStrokes(worldView, regions, pf(mx, my), style);
		}

		// Only the strokes on the player's floor show.
		int plane = worldView.getPlane();
		for (int region : regions)
		{
			for (Stroke s : regionStrokes(region))
			{
				if ((showOwnStrokes || s == currentStroke) && s.plane == plane)
				{
					visibleStrokes.add(s);
				}
			}
		}
		partySync.forEachVisibleStroke(regions, plane, visibleStrokes::add);

		// Draw the strokes of all players together, from the oldest to the newest, so that a new stroke is on top.
		// The strokes are mostly in order already, so the sort is fast.
		visibleStrokes.sort(Stroke.DRAW_ORDER);
		try
		{
			// Count from the newest stroke back, so that the newest strokes draw if there are too many points.
			int first = visibleStrokes.size();
			int points = 0;
			while (first > 0 && points + visibleStrokes.get(first - 1).pts.size() <= MAX_DRAWN_POINTS)
			{
				first--;
				points += visibleStrokes.get(first).pts.size();
			}
			for (int i = first; i < visibleStrokes.size(); i++)
			{
				drawStroke(graphics, worldView, visibleStrokes.get(i), style);
			}
		}
		finally
		{
			visibleStrokes.clear();
		}
	}

	/** Removes and saves the local player's shown strokes that are near the point, and tells party members. */
	private void eraseOwnStrokes(WorldView worldView, int[] regions, pf eraseAt, LineStyle style)
	{
		// Strokes on other floors do not show, so the eraser does not touch them.
		int plane = worldView.getPlane();
		for (int region : regions)
		{
			List<Stroke> strokes = regionStrokes(region);
			List<Stroke> toErase = null;
			for (Stroke s : strokes)
			{
				if ((showOwnStrokes || s == currentStroke) && s.plane == plane && buildPath(worldView, s, eraseAt, style))
				{
					if (toErase == null)
					{
						toErase = new ArrayList<>();
					}
					toErase.add(s);
				}
			}

			if (toErase != null)
			{
				strokes.removeAll(toErase);
				saveStrokes(region);
				partySync.onStrokesErased(toErase);
				recordErase(toErase);
			}
		}
	}

	private BasicStroke basicStroke = newBasicStroke(1f);

	private static BasicStroke newBasicStroke(float width)
	{
		return new BasicStroke(width, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	}

	private BasicStroke basicStroke(double width)
	{
		if (basicStroke.getLineWidth() != (float) width)
		{
			basicStroke = newBasicStroke((float) width);
		}
		return basicStroke;
	}

	// Reused for each stroke, so drawing does not make new objects on each frame.
	private final Path2D.Float path = new Path2D.Float();
	// The screen position of one point in buildPath. Reused for each point.
	private final pf projected = pf(0, 0);
	// The screen positions of a run: points in a row that are all on the screen.
	private float[] runX = new float[64];
	private float[] runY = new float[64];
	private int runLength = 0;

	private void addToRun(float x, float y)
	{
		if (runLength == runX.length)
		{
			runX = Arrays.copyOf(runX, runLength * 2);
			runY = Arrays.copyOf(runY, runLength * 2);
		}
		runX[runLength] = x;
		runY[runLength] = y;
		runLength++;
	}

	/** Adds the run to the path with the line style, then empties the run. */
	private void endRun(LineStyle style)
	{
		int n = runLength;
		runLength = 0;
		if (n == 0)
		{
			return;
		}

		float[] x = runX;
		float[] y = runY;
		path.moveTo(x[0], y[0]);
		if (n == 1)
		{
			// A very short line with round caps draws a dot with the width of the stroke.
			path.lineTo(x[0] + 0.01f, y[0]);
		}
		else if (n == 2 || style == LineStyle.STRAIGHT)
		{
			for (int i = 1; i < n; i++)
			{
				path.lineTo(x[i], y[i]);
			}
		}
		else if (style == LineStyle.SMOOTH)
		{
			// Each point is the control point of a quadratic curve between the midpoints of its two segments.
			path.lineTo((x[0] + x[1]) / 2, (y[0] + y[1]) / 2);
			for (int i = 1; i < n - 1; i++)
			{
				path.quadTo(x[i], y[i], (x[i] + x[i + 1]) / 2, (y[i] + y[i + 1]) / 2);
			}
			path.lineTo(x[n - 1], y[n - 1]);
		}
		else
		{
			// A Catmull-Rom spline, as cubic Bezier curves. The first and last points are used again as their own neighbors.
			for (int i = 0; i < n - 1; i++)
			{
				int prev = Math.max(i - 1, 0);
				int next = Math.min(i + 2, n - 1);
				path.curveTo(
					x[i] + (x[i + 1] - x[prev]) / 6, y[i] + (y[i + 1] - y[prev]) / 6,
					x[i + 1] - (x[next] - x[i]) / 6, y[i + 1] - (y[next] - y[i]) / 6,
					x[i + 1], y[i + 1]);
			}
		}
	}

	private void drawStroke(Graphics2D graphics, WorldView worldView, Stroke s, LineStyle style)
	{
		buildPath(worldView, s, null, style);
		graphics.setColor(transparentStrokes ? s.color : s.opaqueColor());
		graphics.setStroke(basicStroke(screenWidth(s.strokeWidth)));
		graphics.draw(path);
	}

	/** Puts the stroke with the current camera in path. If eraseAt is not null, returns true when the stroke is near that point. */
	private boolean buildPath(WorldView worldView, Stroke s, pf eraseAt, LineStyle style)
	{
		boolean hit = false;
		path.reset();
		runLength = 0;

		// Consecutive points are often on the same tile, so project each tile once.
		int tileX = Integer.MIN_VALUE, tileY = Integer.MIN_VALUE;
		Polygon poly = null;
		for (StrokePoint p : s.pts)
		{
			if (p.getX() != tileX || p.getY() != tileY)
			{
				tileX = p.getX();
				tileY = p.getY();
				LocalPoint lp = isInRenderDistance(worldView, tileX, tileY) ? loadedLocalPoint(worldView, tileX, tileY, s.plane) : null;
				poly = lp != null ? Perspective.getCanvasTilePoly(client, lp) : null;
			}

			if (poly == null)
			{
				// The tile is not in the scene, not in the render distance or not on the screen, so the line breaks here.
				// Without the break, a stroke that leaves the scene and comes back is joined across the gap.
				endRun(style);
				continue;
			}
			pf screen = projectToScreen(p.getSubx(), p.getSuby(), poly, projected);
			// The eraser has a radius of 10 pixels, so it hits a wide stroke at its edge.
			// The first point of a run has no line before it, so the test uses the point alone.
			// Thus the eraser also hits a stroke that is one dot.
			if (eraseAt != null && !hit)
			{
				float fromX = runLength > 0 ? runX[runLength - 1] : screen.x;
				float fromY = runLength > 0 ? runY[runLength - 1] : screen.y;
				hit = Line2D.ptSegDist(fromX, fromY, screen.x, screen.y, eraseAt.x, eraseAt.y) < 10 + screenWidth(s.strokeWidth) / 2;
			}
			addToRun(screen.x, screen.y);
		}
		endRun(style);
		return hit;
	}

	/** Returns the box that button i draws in. It is the same rectangle for each button, so use it before the next call. */
	private Rectangle toolbarButtonVisibleBounds(int i) {
		drawBounds.setBounds(clickboxes[i]);
		drawBounds.grow(-1, -1);
		return drawBounds;
	}

	// "New color" and "Reset palette" make the top row. The color slots go below them.
	// Under the color slots, "Decrease" and "Increase" stroke size make one row, and the size number is under them.
	private static final int TOP_ROW_BUTTONS = 2;
	private static final int SIZE_BUTTONS_START = TOP_ROW_BUTTONS + COLOR_SLOTS;
	private static final int SIZE_ROW = SLOTS_PER_COLUMN + 1;

	/** Returns the click box of button i. Do not change the rectangle. */
	private Rectangle toolbarButtonClickbox(int i) {
		return clickboxes[i];
	}

	private static Rectangle[] layoutClickboxes(int count) {
		Rectangle[] boxes = new Rectangle[count];
		for (int i = 0; i < count; i++) {
			boxes[i] = layoutClickbox(i);
		}
		return boxes;
	}

	private static Rectangle layoutClickbox(int i) {
		int column, row;
		if (i < TOP_ROW_BUTTONS) {
			column = i;
			row = 0;
		} else if (i < SIZE_BUTTONS_START) {
			column = (i - TOP_ROW_BUTTONS) / SLOTS_PER_COLUMN;
			row = (i - TOP_ROW_BUTTONS) % SLOTS_PER_COLUMN + 1;
		} else if (i < SIZE_BUTTONS_START + 2) {
			column = i - SIZE_BUTTONS_START;
			row = SIZE_ROW;
		} else {
			// The size number is as wide as the two buttons above it.
			return new Rectangle(2, 40 + 20 * (SIZE_ROW + 1), 36, 16);
		}
		return new Rectangle(2 + 20 * column, 40 + 20 * row, 16, 16);
	}

	private int getMousedOverToolbarButton(int mx, int my) {
		for (int i = 0; i < buttons.size(); i++)
		{
			if (toolbarButtonClickbox(i).contains(mx, my)) {
				return i;
			}
		}
		return -1;
	}

	boolean dDown = false; // draw keybind is held, or draw mode is on if toggleModes is on.
	boolean drawing = false; // mouse is down and drawing.
	boolean eDown = false; // erase keybind is held, or erase mode is on if toggleModes is on.
	boolean erasing = false; // mouse is down and erasing.
	boolean drawable = false; // last menu entries contained WALK, or SET_HEADING while the player steers a boat.

	// The draw and erase keys are down. Key repeat sends more presses, so toggleModes toggles only on the first one.
	private boolean drawKeyHeld = false;
	private boolean eraseKeyHeld = false;
	// Undo or redo consumed a key press, so its typed character must not reach the game either.
	private boolean consumeTyped = false;

	/** True if the toolbar is on the screen. This is the same test that render() uses. */
	private boolean isToolbarShown()
	{
		return eDown || dDown || drawing || erasing;
	}

	int toolbarButtonBeingDraggedIndex = -1;

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		if (e.getButton() != MouseEvent.BUTTON1) return e;

		// A press on an open menu picks a menu entry. It does not start a drag.
		toolbarButtonBeingDraggedIndex = -1;
		if (client.isMenuOpen()) return e;

		// The hidden toolbar takes no clicks.
		if (isToolbarShown()) {
			toolbarButtonBeingDraggedIndex = getMousedOverToolbarButton(e.getX(), e.getY());
		}
		if (toolbarButtonBeingDraggedIndex != -1) {
			if (isSizeButton(toolbarButtonBeingDraggedIndex)) {
				// Write the time first. The client thread reads the button first, then the time.
				heldSince = System.currentTimeMillis();
				heldSizeButton = toolbarButtonBeingDraggedIndex;
			}
			return e;
		}

		if (drawable) {
			if (dDown) drawing = true;
			else if (eDown) erasing = true;
		}

		return e;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		if (e.getButton() != MouseEvent.BUTTON1) return e;

		// A release on an open menu or on the hidden toolbar does not drop on a button.
		int i = !client.isMenuOpen() && isToolbarShown() ? getMousedOverToolbarButton(e.getX(), e.getY()) : -1;
		if (i != -1 && toolbarButtonBeingDraggedIndex != -1) {
			buttons.get(i).onDrag(buttons.get(toolbarButtonBeingDraggedIndex));
		}

		// Always end the drag and the held size button, also if a menu opened during the press.
		toolbarButtonBeingDraggedIndex = -1;
		drawing = false;
		erasing = false;
		heldSizeButton = -1;
		return e;
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		if (config.drawKeybind().matches(e)) {
			if (!config.toggleModes()) dDown = true;
			else if (!drawKeyHeld) setMode(!dDown, false);
			drawKeyHeld = true;
		} else if (config.eraseKeybind().matches(e)) {
			if (!config.toggleModes()) eDown = true;
			else if (!eraseKeyHeld) setMode(false, !eDown);
			eraseKeyHeld = true;
		} else if (dDown || eDown) {
			// Undo and redo work only in draw mode or erase mode. In other modes the keys go to the game.
			if (config.undoKeybind().matches(e)) {
				e.consume();
				consumeTyped = true;
				clientThread.invoke(this::undo);
			} else if (config.redoKeybind().matches(e)) {
				e.consume();
				consumeTyped = true;
				clientThread.invoke(this::redo);
			}
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		if (config.drawKeybind().matches(e)) {
			drawKeyHeld = false;
			if (!config.toggleModes()) dDown = false;
		} else if (config.eraseKeybind().matches(e)) {
			eraseKeyHeld = false;
			if (!config.toggleModes()) eDown = false;
		}
		// Some keys, for example F5 or the arrow keys, make no typed character. If the flag stays on,
		// keyTyped eats the next character that the player types. The typed character comes before the release.
		consumeTyped = false;
	}

	private void setMode(boolean draw, boolean erase)
	{
		dDown = draw;
		eDown = erase;
		drawing = false;
		erasing = false;
	}

	@Subscribe public void onFocusChanged(FocusChanged e) {
		if (!e.isFocused()) {
			// The keys and the mouse button can be released outside the client.
			if (!config.toggleModes()) {
				dDown = false;
				eDown = false;
			}
			drawKeyHeld = false;
			eraseKeyHeld = false;
			consumeTyped = false;
			drawing = false;
			erasing = false;
			heldSizeButton = -1;
		}
	}

	@Override public void keyTyped(KeyEvent e) {
		// Most key presses also make a typed character. It must not reach the game either.
		if (consumeTyped) {
			consumeTyped = false;
			e.consume();
		}
	}
	@Override public MouseEvent mouseClicked(MouseEvent e) { return e; }
	@Override public MouseEvent mouseEntered(MouseEvent e) { return e; }
	@Override public MouseEvent mouseExited(MouseEvent e) { return e; }
	@Override public MouseEvent mouseDragged(MouseEvent e) { return e; }
	@Override public MouseEvent mouseMoved(MouseEvent e) { return e; }

	public void startUp() {
		showOwnStrokes = true;
		resetCanvas();

		Integer savedSize = configManager.getConfiguration(RsPaintConfig.GROUP, "strokeSize", Integer.class);
		strokeSize = savedSize != null ? Math.max(Stroke.MIN_WIDTH, Math.min(Stroke.MAX_WIDTH, savedSize)) : Stroke.MIN_WIDTH;

		String configuration = configManager.getConfiguration(RsPaintConfig.GROUP, "drawColors");
		Color[] savedArray = configuration != null ? gson.fromJson(configuration, Color[].class) : null;
		List<Color> saved = savedArray != null ? new ArrayList<>(Arrays.asList(savedArray)) : null;
		if (saved == null || isOldDefaultPalette(saved)) {
			useDefaultPalette();
			return;
		}
		while (saved.size() < COLOR_SLOTS) {
			saved.add(null);
		}
		colors = saved;
	}

	/** Frees the loaded strokes and the history while the plugin is off. */
	public void shutDown() {
		clientThread.invokeLater(this::resetCanvas);
	}

	/**
	 * Forgets the loaded strokes and the history. The overlay is a singleton, so without this the strokes of the old
	 * profile or the last session stay loaded, and the next save writes them over the saved strokes.
	 */
	private void resetCanvas() {
		strokesByRegion.clear();
		unreadableRegions.clear();
		warnedRegions.clear();
		undoStack.clear();
		redoStack.clear();
		currentStroke = null;
		skippedPoint = null;
		currentErase = null;
	}

	@Subscribe public void onProfileChanged(ProfileChanged e) {
		clientThread.invoke(() -> {
			// The new profile has its own strokes, colors and stroke size.
			startUp();
			// Party members still have the strokes of the old profile.
			partySync.onCanvasCleared();
			WorldView worldView = client.getTopLevelWorldView();
			if (client.getGameState() == GameState.LOGGED_IN && worldView != null) {
				loadStrokes(sceneRegions(worldView));
			}
		});
	}

	private void useDefaultPalette() {
		colors = new ArrayList<>(Arrays.asList(DEFAULT_PALETTE));
		while (colors.size() < COLOR_SLOTS) {
			colors.add(null);
		}
		saveColors();
	}

	/** True if the saved palette is the old one-color default, so the player never chose a color. */
	private static boolean isOldDefaultPalette(List<Color> saved) {
		for (int i = 0; i < saved.size(); i++) {
			Color color = saved.get(i);
			if (color != null && !(i == 0 && color.equals(DEFAULT_COLOR))) {
				return false;
			}
		}
		return true;
	}

	static float triangleArea(int x1, int y1, int x2, int y2, int x3, int y3)
	{
		// Divide as a float. An integer division drops the half-pixel areas.
		return Math.abs((x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) / 2f);
	}
}

package com.rspaint;

import com.google.gson.annotations.JsonAdapter;
import com.google.gson.annotations.SerializedName;
import com.rspaint.RsPaintPlugin.Stroke;
import com.rspaint.RsPaintPlugin.StrokeClock;
import com.rspaint.RsPaintPlugin.StrokePoint;
import java.awt.Color;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.Deque;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.EqualsAndHashCode;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PartyChanged;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.party.events.UserJoin;
import net.runelite.client.party.events.UserPart;
import net.runelite.client.party.messages.PartyMemberMessage;
import net.runelite.client.party.messages.PartyMessage;
import net.runelite.client.party.messages.UserSync;

/** Sends the local canvas to party members and keeps a copy of each other member's canvas. */
@Slf4j
@Singleton
public class PartyCanvasSync
{
	private static final long FLUSH_INTERVAL_MS = 200;
	// A full sync goes out at most once in this time. If members join or ask during the wait, one full sync answers all of them.
	private static final long FULL_SYNC_INTERVAL_MS = 10_000;

	// Payload of one stroke in a message, measured with Gson: about 76 bytes for the stroke and 2.7 bytes for each point.
	// The plane adds 6 bytes ("z":0,) to the stroke. StrokeCodec encodes the points. As plain JSON objects, each point was about 55 bytes.
	private static final int STROKE_BYTES = 86;
	private static final int POINT_BYTES = 3;
	// Complete strokes go out in messages of at most about this many bytes.
	private static final int MAX_MESSAGE_BYTES = 32 * 1024;

	// A full sync sends only the newest strokes, so that a big canvas does not flood the party.
	// Older strokes stay on your screen, but party members lose them on the next full sync.
	// A stroke gets at most one point each frame, so a line drawn in 1 second at 50 FPS has about 50 points.
	// StrokeCodec.simplify keeps about 25 of them. Then 1000 strokes are about 150 KB in about 5 messages.
	// A line of 200 points keeps about 100, and 1000 of those are about 390 KB in about 12 messages.
	// A full sync also sends at most MAX_MEMBER_POINTS points, and MAX_FLUSH_BYTES spreads its messages over several flushes.
	// A member canvas also keeps only this many strokes, the newest ones, so a member cannot fill your memory.
	private static final int MAX_SYNCED_STROKES = 1000;
	// A member canvas keeps at most this many points in each stroke, and drops the points after them.
	// Members send the points of a stroke while it is drawn, before simplify. A stroke gets at most one point each frame,
	// and only after the mouse moves 3 screen pixels. So 5000 points are a line of at least 15000 pixels, about 8 times
	// across a 1920-pixel screen, and more than 1.5 minutes of drawing without a stop at 50 FPS. Real strokes are much shorter.
	private static final int MAX_STROKE_POINTS = 5000;
	// A member canvas keeps at most this many points in all its strokes. If a member sends more, the oldest strokes go.
	// Without this limit, one member could send 1000 strokes of 5000 points, and drawing them would freeze the client.
	// A full sync of 1000 strokes that simplify keeps at 100 points each fits.
	private static final int MAX_MEMBER_POINTS = 100_000;
	// One flush sends messages of at most about this many bytes in all. The other messages wait for the next flushes,
	// so a full sync of about 390 KB goes out in about 2.5 seconds, not in one burst. A message that is larger goes out alone.
	private static final int MAX_FLUSH_BYTES = 32 * 1024;
	// Payload of one id in an erase message: about 13 characters, the quotes and a comma.
	private static final int ID_BYTES = 16;
	// The party has the strokes with these ids, so a region load does not send them again.
	// At most this many ids are kept. A stroke whose id is forgotten goes out again on the next load of its region.
	private static final int MAX_SENT_IDS = 10 * MAX_SYNCED_STROKES;

	@Inject private ClientThread clientThread;
	@Inject private PartyService partyService;
	@Inject private WSClient wsClient;
	@Inject private StrokeClock clock;

	// Client thread only.
	private final Map<Long, MemberCanvas> canvases = new HashMap<>();
	// Changed from the Swing thread by the side panel.
	private final Set<Long> hiddenMembers = ConcurrentHashMap.newKeySet();

	// Outgoing changes waiting for the next flush. Client thread only.
	private final Map<Stroke, List<StrokePoint>> pendingPoints = new LinkedHashMap<>();
	private final List<String> pendingErases = new ArrayList<>();
	// Strokes that undo, redo, a region load or an import put back. They go out complete and replace the receiver's copy.
	private final Set<Stroke> pendingRestores = new LinkedHashSet<>();
	// Messages that wait to go out, in the order they must arrive. Each flush sends at most MAX_FLUSH_BYTES of them.
	// Client thread only.
	private final Deque<Outgoing> outbox = new ArrayDeque<>();
	// Ids of the local strokes that the party has since the last full sync, the oldest first. Client thread only.
	private final Set<String> sentIds = new LinkedHashSet<>();
	private boolean fullSyncPending = false;
	private boolean canvasRequestPending = false;
	// Times from monotonicMillis, or NEVER. The wall clock is not used, because it can go back.
	private static final long NEVER = Long.MIN_VALUE;
	private long lastFlush = NEVER;
	private long lastFullSync = NEVER;

	void startUp()
	{
		wsClient.registerMessage(RsPaintStrokeAppend.class);
		wsClient.registerMessage(RsPaintStrokeErase.class);
		wsClient.registerMessage(RsPaintCanvasSync.class);
		wsClient.registerMessage(RsPaintCanvasClear.class);
		wsClient.registerMessage(RsPaintCanvasRequest.class);

		clientThread.invokeLater(() -> {
			fullSyncPending = true;
			canvasRequestPending = true;
		});
	}

	void shutDown()
	{
		wsClient.unregisterMessage(RsPaintStrokeAppend.class);
		wsClient.unregisterMessage(RsPaintStrokeErase.class);
		wsClient.unregisterMessage(RsPaintCanvasSync.class);
		wsClient.unregisterMessage(RsPaintCanvasClear.class);
		wsClient.unregisterMessage(RsPaintCanvasRequest.class);

		// The overlay is already removed, so no flush can follow this clear.
		clientThread.invokeLater(() -> {
			if (canSend())
			{
				send(new RsPaintCanvasClear());
			}
			canvases.clear();
			clearPending();
		});
		hiddenMembers.clear();
	}

	boolean isMemberVisible(long memberId)
	{
		return !hiddenMembers.contains(memberId);
	}

	void setMemberVisible(long memberId, boolean visible)
	{
		if (visible)
		{
			hiddenMembers.remove(memberId);
		}
		else
		{
			hiddenMembers.add(memberId);
		}
	}

	/** Gives each stroke of the shown members that is in the regions and on the plane to the action. */
	void forEachVisibleStroke(int[] regions, int plane, Consumer<Stroke> action)
	{
		if (regions == null)
		{
			return;
		}

		for (Map.Entry<Long, MemberCanvas> entry : canvases.entrySet())
		{
			if (hiddenMembers.contains(entry.getKey()))
			{
				continue;
			}

			for (int region : regions)
			{
				List<Stroke> strokes = entry.getValue().strokesByRegion.get(region);
				if (strokes == null)
				{
					continue;
				}
				for (Stroke stroke : strokes)
				{
					if (stroke.plane == plane)
					{
						action.accept(stroke);
					}
				}
			}
		}
	}

	/** Returns a copy of the member's strokes. Client thread only. */
	List<SyncedStroke> memberStrokes(long memberId)
	{
		List<SyncedStroke> result = new ArrayList<>();
		MemberCanvas canvas = canvases.get(memberId);
		if (canvas != null)
		{
			for (Stroke stroke : canvas.strokesById.values())
			{
				result.add(toSynced(stroke, stroke.pts));
			}
		}
		return result;
	}

	/** Returns a copy of the strokes of all members that are not hidden. Client thread only. */
	List<SyncedStroke> visibleMemberStrokes()
	{
		List<SyncedStroke> result = new ArrayList<>();
		for (Long memberId : canvases.keySet())
		{
			if (!hiddenMembers.contains(memberId))
			{
				result.addAll(memberStrokes(memberId));
			}
		}
		return result;
	}

	void onPointAdded(Stroke stroke, StrokePoint point)
	{
		// Receivers keep at most MAX_STROKE_POINTS points of a stroke, so the points after them do not go out.
		if (partyService.isInParty() && stroke.pts.size() <= MAX_STROKE_POINTS)
		{
			pendingPoints.computeIfAbsent(stroke, k -> new ArrayList<>()).add(point);
		}
	}

	void onStrokesErased(Collection<Stroke> strokes)
	{
		if (!partyService.isInParty())
		{
			return;
		}

		for (Stroke stroke : strokes)
		{
			pendingPoints.remove(stroke);
			pendingRestores.remove(stroke);
			pendingErases.add(stroke.id);
			sentIds.remove(stroke.id);
		}
	}

	/**
	 * Sends the complete strokes on the next flush, without a reset. Each stroke replaces the receiver's copy.
	 * Undo, redo, region loads and imports use this. A stroke that the party has already does not go out again,
	 * for example a stroke of a region that loads again after a teleport. Client thread only.
	 */
	void onStrokesRestored(Collection<Stroke> strokes)
	{
		if (!partyService.isInParty())
		{
			return;
		}

		for (Stroke stroke : strokes)
		{
			// An erase removes the id from sentIds, so undo of an erase and redo of a draw always send the stroke.
			if (sentIds.contains(stroke.id))
			{
				continue;
			}
			// If the erase is not sent yet, receivers still have the stroke. A replace is correct in both cases.
			pendingErases.remove(stroke.id);
			pendingPoints.remove(stroke);
			pendingRestores.add(stroke);
		}
	}

	void onCanvasCleared()
	{
		clearPending();
		if (canSend())
		{
			send(new RsPaintCanvasClear());
		}
	}

	/** Called on each client tick. Sends at most once per FLUSH_INTERVAL_MS. */
	void flush(Map<Integer, List<Stroke>> localStrokesByRegion)
	{
		long now = monotonicMillis();
		if (!hasElapsed(lastFlush, now, FLUSH_INTERVAL_MS))
		{
			return;
		}
		lastFlush = now;

		if (!canSend())
		{
			clearPending();
			return;
		}

		// Drop the pending changes even if a send fails, so the error does not repeat on every tick.
		try
		{
			queuePending(localStrokesByRegion, now);
			sendFromOutbox();
		}
		catch (RuntimeException e)
		{
			log.warn("Could not send canvas changes to the party", e);
			outbox.clear();
		}
		finally
		{
			pendingPoints.clear();
			pendingErases.clear();
			pendingRestores.clear();
		}
	}

	/** Sends the oldest messages of the outbox, at most about MAX_FLUSH_BYTES in all, but always at least one message. */
	private void sendFromOutbox()
	{
		int bytes = 0;
		while (!outbox.isEmpty())
		{
			Outgoing next = outbox.peekFirst();
			if (bytes > 0 && bytes + next.bytes > MAX_FLUSH_BYTES)
			{
				return;
			}
			outbox.removeFirst();
			bytes += next.bytes;
			send(next.message);
		}
	}

	private void markSent(String id)
	{
		// Move the id to the end, so the oldest ids are forgotten first.
		sentIds.remove(id);
		sentIds.add(id);
		if (sentIds.size() > MAX_SENT_IDS)
		{
			Iterator<String> oldest = sentIds.iterator();
			oldest.next();
			oldest.remove();
		}
	}

	/** Returns at most the first MAX_STROKE_POINTS points, because receivers drop the points after them. */
	private static List<StrokePoint> sentPoints(Stroke stroke)
	{
		return stroke.pts.size() > MAX_STROKE_POINTS ? stroke.pts.subList(0, MAX_STROKE_POINTS) : stroke.pts;
	}

	/**
	 * Returns the newest strokes of the list that a receiver keeps: at most MAX_SYNCED_STROKES strokes and
	 * MAX_MEMBER_POINTS sent points. The list must be in draw order. Strokes without points are skipped.
	 */
	private static List<Stroke> newestKept(List<Stroke> strokes)
	{
		List<Stroke> kept = new ArrayList<>();
		int points = 0;
		for (int i = strokes.size() - 1; i >= 0 && kept.size() < MAX_SYNCED_STROKES; i--)
		{
			Stroke stroke = strokes.get(i);
			int size = sentPoints(stroke).size();
			if (size == 0)
			{
				continue;
			}
			if (points + size > MAX_MEMBER_POINTS)
			{
				break;
			}
			points += size;
			kept.add(stroke);
		}
		Collections.reverse(kept);
		return kept;
	}

	/** Returns milliseconds from System.nanoTime. Only the difference of two values has a meaning. */
	private static long monotonicMillis()
	{
		return System.nanoTime() / 1_000_000;
	}

	private static boolean hasElapsed(long since, long now, long intervalMs)
	{
		return since == NEVER || now - since >= intervalMs;
	}

	/**
	 * Puts the pending changes into the outbox as messages. The outbox keeps their order, so a receiver gets each change
	 * after the changes before it, also when the messages go out over several flushes.
	 */
	private void queuePending(Map<Integer, List<Stroke>> localStrokesByRegion, long now)
	{
		if (canvasRequestPending)
		{
			canvasRequestPending = false;
			// The answers do not depend on the order of the other messages, so the request does not wait in the outbox.
			send(new RsPaintCanvasRequest());
		}

		// If the last full sync is too recent, the full sync stays pending and goes out on a later flush.
		// It reads the canvas when it is queued, so it has all changes from the wait.
		if (fullSyncPending && hasElapsed(lastFullSync, now, FULL_SYNC_INTERVAL_MS))
		{
			fullSyncPending = false;
			lastFullSync = now;
			// The reset removes all earlier strokes on the receivers, so the messages before it are not needed.
			outbox.clear();
			sentIds.clear();
			List<Stroke> strokes = new ArrayList<>();
			localStrokesByRegion.values().forEach(strokes::addAll);
			// Receivers sort by the order in each stroke. Old versions of the plugin use the message order.
			strokes.sort(Stroke.DRAW_ORDER);
			queueCompleteStrokes(newestKept(strokes), true);
		}

		// After the full sync, so that its reset does not remove these strokes again.
		if (!pendingRestores.isEmpty())
		{
			// A big import can restore many strokes. Receivers keep only the newest strokes, so send only those.
			List<Stroke> strokes = new ArrayList<>(pendingRestores);
			strokes.sort(Stroke.DRAW_ORDER);
			queueCompleteStrokes(newestKept(strokes), false);
		}

		if (!pendingPoints.isEmpty())
		{
			List<SyncedStroke> strokes = new ArrayList<>();
			int bytes = 0;
			for (Map.Entry<Stroke, List<StrokePoint>> entry : pendingPoints.entrySet())
			{
				strokes.add(toSynced(entry.getKey(), entry.getValue()));
				bytes += STROKE_BYTES + POINT_BYTES * entry.getValue().size();
				markSent(entry.getKey().id);
			}
			outbox.addLast(new Outgoing(new RsPaintStrokeAppend(strokes), bytes));
		}

		if (!pendingErases.isEmpty())
		{
			outbox.addLast(new Outgoing(new RsPaintStrokeErase(new ArrayList<>(pendingErases)), ID_BYTES * pendingErases.size()));
		}
	}

	/**
	 * Queues the complete strokes in chunks of about MAX_MESSAGE_BYTES at most. A stroke larger than that goes in a chunk
	 * alone. Each stroke goes out with at most MAX_STROKE_POINTS points. If reset is true, the first chunk resets the
	 * receiver's canvas. Without a reset, each stroke replaces the receiver's copy.
	 */
	private void queueCompleteStrokes(List<Stroke> strokes, boolean reset)
	{
		List<SyncedStroke> chunk = new ArrayList<>();
		int chunkBytes = 0;
		for (Stroke stroke : strokes)
		{
			List<StrokePoint> points = sentPoints(stroke);
			if (points.isEmpty())
			{
				continue;
			}

			pendingPoints.remove(stroke);

			int strokeBytes = STROKE_BYTES + POINT_BYTES * points.size();
			if (!chunk.isEmpty() && chunkBytes + strokeBytes > MAX_MESSAGE_BYTES)
			{
				outbox.addLast(new Outgoing(new RsPaintCanvasSync(reset, chunk), chunkBytes));
				reset = false;
				chunk = new ArrayList<>();
				chunkBytes = 0;
			}
			chunk.add(toSynced(stroke, points));
			chunkBytes += strokeBytes;
			markSent(stroke.id);
		}

		// A reset goes out even when empty, so receivers drop old strokes.
		if (!chunk.isEmpty() || reset)
		{
			outbox.addLast(new Outgoing(new RsPaintCanvasSync(reset, chunk), chunkBytes));
		}
	}

	/** A message in the outbox, with its estimated payload in bytes. */
	@Value
	private static class Outgoing
	{
		PartyMessage message;
		int bytes;
	}

	static SyncedStroke toSynced(Stroke stroke, List<StrokePoint> points)
	{
		return new SyncedStroke(stroke.id, stroke.color.getRGB(), stroke.strokeWidth, stroke.order, stroke.plane, new ArrayList<>(points));
	}

	/** Returns a local stroke with the id, draw order and points of the synced stroke. A stroke without an id gets a new id. */
	static Stroke fromSynced(SyncedStroke synced)
	{
		Stroke stroke = new Stroke();
		if (synced.getId() != null)
		{
			stroke.id = synced.getId();
		}
		stroke.color = new Color(synced.getColor(), true);
		stroke.strokeWidth = synced.getStrokeWidth();
		stroke.order = synced.getOrder();
		stroke.plane = synced.getPlane();
		stroke.pts.addAll(synced.getPoints());
		return stroke;
	}

	private boolean canSend()
	{
		return partyService.isInParty() && partyService.getLocalMember() != null;
	}

	private void send(PartyMessage message)
	{
		try
		{
			partyService.send(message);
		}
		catch (IllegalStateException e)
		{
			log.debug("Could not send party message {}", message, e);
		}
	}

	private void clearPending()
	{
		pendingPoints.clear();
		pendingErases.clear();
		pendingRestores.clear();
		outbox.clear();
		// Callers clear the receivers' copy of the canvas, or the party is gone.
		sentIds.clear();
		fullSyncPending = false;
		canvasRequestPending = false;
	}

	/** Returns the sender's canvas, or null if the sender is the local player or not in the party. */
	private MemberCanvas canvasFor(PartyMemberMessage message)
	{
		PartyMember local = partyService.getLocalMember();
		if (local != null && local.getMemberId() == message.getMemberId())
		{
			return null;
		}
		if (partyService.getMemberById(message.getMemberId()) == null)
		{
			return null;
		}
		return canvases.computeIfAbsent(message.getMemberId(), k -> new MemberCanvas());
	}

	@Subscribe
	public void onRsPaintStrokeAppend(RsPaintStrokeAppend message)
	{
		clientThread.invokeLater(() -> {
			MemberCanvas canvas = canvasFor(message);
			if (canvas != null && message.getStrokes() != null)
			{
				message.getStrokes().forEach(canvas::append);
			}
		});
	}

	@Subscribe
	public void onRsPaintStrokeErase(RsPaintStrokeErase message)
	{
		clientThread.invokeLater(() -> {
			MemberCanvas canvas = canvasFor(message);
			if (canvas != null && message.getStrokeIds() != null)
			{
				message.getStrokeIds().forEach(canvas::remove);
			}
		});
	}

	@Subscribe
	public void onRsPaintCanvasSync(RsPaintCanvasSync message)
	{
		clientThread.invokeLater(() -> {
			MemberCanvas canvas = canvasFor(message);
			if (canvas == null)
			{
				return;
			}
			if (message.isReset())
			{
				canvas.clear();
			}
			if (message.getStrokes() != null)
			{
				message.getStrokes().forEach(canvas::replace);
			}
		});
	}

	@Subscribe
	public void onRsPaintCanvasClear(RsPaintCanvasClear message)
	{
		clientThread.invokeLater(() -> {
			MemberCanvas canvas = canvasFor(message);
			if (canvas != null)
			{
				canvas.clear();
			}
		});
	}

	/** Returns true if the local player sent the message. The party server sends each message back to its sender too. */
	private boolean isFromLocalMember(PartyMemberMessage message)
	{
		PartyMember local = partyService.getLocalMember();
		return local != null && local.getMemberId() == message.getMemberId();
	}

	// Our own request comes back too. startUp already queued our full sync, so ignore it.
	@Subscribe
	public void onRsPaintCanvasRequest(RsPaintCanvasRequest message)
	{
		clientThread.invokeLater(() -> {
			if (!isFromLocalMember(message))
			{
				fullSyncPending = true;
			}
		});
	}

	// A joining member sends UserSync. Our own UserSync comes back too. onUserJoin already queued our full sync, so ignore it.
	@Subscribe
	public void onUserSync(UserSync message)
	{
		clientThread.invokeLater(() -> {
			if (!isFromLocalMember(message))
			{
				fullSyncPending = true;
			}
		});
	}

	@Subscribe
	public void onUserJoin(UserJoin event)
	{
		clientThread.invokeLater(() -> {
			PartyMember local = partyService.getLocalMember();
			if (local != null && local.getMemberId() == event.getMemberId())
			{
				fullSyncPending = true;
			}
		});
	}

	@Subscribe
	public void onUserPart(UserPart event)
	{
		clientThread.invokeLater(() -> canvases.remove(event.getMemberId()));
		hiddenMembers.remove(event.getMemberId());
	}

	@Subscribe
	public void onPartyChanged(PartyChanged event)
	{
		clientThread.invokeLater(() -> {
			canvases.clear();
			clearPending();
			// The members of the new party do not have the canvas yet, so the wait does not apply to them.
			lastFullSync = NEVER;
		});
		hiddenMembers.clear();
	}

	private class MemberCanvas
	{
		final Map<Integer, List<Stroke>> strokesByRegion = new HashMap<>();
		final Map<String, Stroke> strokesById = new HashMap<>();
		// The same strokes in draw order, so the oldest stroke is first.
		final TreeSet<Stroke> strokesByOrder = new TreeSet<>(Stroke.DRAW_ORDER);
		// The number of points in all strokes of the canvas.
		int totalPoints = 0;

		void append(SyncedStroke synced)
		{
			Stroke stroke = strokesById.get(synced.getId());
			if (stroke == null)
			{
				add(synced);
			}
			else if (synced.getPoints() != null)
			{
				totalPoints += addPoints(stroke, synced.getPoints());
				removeOldestOverBudget();
			}
		}

		void replace(SyncedStroke synced)
		{
			remove(synced.getId());
			add(synced);
		}

		void remove(String id)
		{
			Stroke stroke = strokesById.remove(id);
			if (stroke != null)
			{
				strokesByOrder.remove(stroke);
				totalPoints -= stroke.pts.size();
				List<Stroke> strokes = strokesByRegion.get(stroke.primaryRegion());
				if (strokes != null)
				{
					strokes.remove(stroke);
				}
			}
		}

		void clear()
		{
			strokesByRegion.clear();
			strokesById.clear();
			strokesByOrder.clear();
			totalPoints = 0;
		}

		private void add(SyncedStroke synced)
		{
			if (synced.getId() == null || synced.getPoints() == null || synced.getPoints().isEmpty()
				|| !Stroke.isValidPlane(synced.getPlane()))
			{
				return;
			}

			Stroke stroke = new Stroke();
			stroke.id = synced.getId();
			stroke.color = new Color(synced.getColor(), true);
			// Do not trust the width from the message. A very large width is slow to draw.
			stroke.strokeWidth = Stroke.validWidth(synced.getStrokeWidth());
			stroke.order = clock.receive(synced.getOrder());
			stroke.plane = synced.getPlane();
			addPoints(stroke, synced.getPoints());

			// Keep the newest MAX_SYNCED_STROKES strokes in draw order, the same strokes as the member's full sync.
			// A new stroke of the member is always the newest, so the oldest kept stroke goes. A stroke that is older
			// than all kept strokes, for example an old stroke that undo puts back, is dropped. A full sync would drop it too.
			if (strokesById.size() >= MAX_SYNCED_STROKES)
			{
				Stroke oldest = strokesByOrder.first();
				if (Stroke.DRAW_ORDER.compare(stroke, oldest) < 0)
				{
					return;
				}
				remove(oldest.id);
			}

			strokesById.put(stroke.id, stroke);
			strokesByOrder.add(stroke);
			strokesByRegion.computeIfAbsent(stroke.primaryRegion(), k -> new ArrayList<>()).add(stroke);
			totalPoints += stroke.pts.size();
			removeOldestOverBudget();
		}

		/** Adds the points to the stroke, but not past MAX_STROKE_POINTS. Returns the number of points added. */
		private int addPoints(Stroke stroke, List<StrokePoint> points)
		{
			int room = MAX_STROKE_POINTS - stroke.pts.size();
			if (room <= 0)
			{
				return 0;
			}
			int added = Math.min(room, points.size());
			stroke.pts.addAll(points.subList(0, added));
			return added;
		}

		/**
		 * Removes the oldest strokes until the canvas has at most MAX_MEMBER_POINTS points.
		 * A stroke has at most MAX_STROKE_POINTS points, so the newest stroke always stays.
		 */
		private void removeOldestOverBudget()
		{
			while (totalPoints > MAX_MEMBER_POINTS && !strokesByOrder.isEmpty())
			{
				remove(strokesByOrder.first().id);
			}
		}
	}

	/**
	 * A stroke, or a part of a stroke, that is sent to party members, exported, or saved as JSON (StrokeStorage version 2).
	 * The JSON names are one letter, and the points are one encoded string, because a full sync can have 1000 strokes.
	 */
	@Value
	static class SyncedStroke
	{
		/** From the stroke that draws first, at the bottom, to the stroke that draws last, on top. */
		static final Comparator<SyncedStroke> DRAW_ORDER = Comparator.comparingLong(SyncedStroke::getOrder)
			.thenComparing(SyncedStroke::getId, Comparator.nullsFirst(Comparator.naturalOrder()));

		@SerializedName("i")
		String id;
		@SerializedName("c")
		int color;
		@SerializedName("w")
		double strokeWidth;
		/** The draw order from StrokeClock. It is 0 if the sender has an old version of the plugin. */
		@SerializedName("o")
		long order;
		/** The plane (floor) of the stroke, from 0 to 3. */
		@SerializedName("z")
		int plane;
		@SerializedName("p")
		@JsonAdapter(StrokeCodec.PointsAdapter.class)
		List<StrokePoint> points;
	}

	// Party messages. The party server finds the class by its simple name, so the names start with RsPaint.

	/** Adds new points to the end of strokes. The receiver makes the stroke if it does not have it yet. */
	@Value
	@EqualsAndHashCode(callSuper = true)
	public static class RsPaintStrokeAppend extends PartyMemberMessage
	{
		List<SyncedStroke> strokes;
	}

	/** Removes strokes from the sender's canvas. */
	@Value
	@EqualsAndHashCode(callSuper = true)
	public static class RsPaintStrokeErase extends PartyMemberMessage
	{
		List<String> strokeIds;
	}

	/**
	 * Sends complete strokes from the sender's canvas.
	 * If reset is true, the receiver removes all of the sender's strokes before it adds these strokes.
	 */
	@Value
	@EqualsAndHashCode(callSuper = true)
	public static class RsPaintCanvasSync extends PartyMemberMessage
	{
		boolean reset;
		List<SyncedStroke> strokes;
	}

	/** Removes all strokes from the sender's canvas. */
	@Value
	@EqualsAndHashCode(callSuper = true)
	public static class RsPaintCanvasClear extends PartyMemberMessage
	{
	}

	/** Asks all party members to send their canvas again. */
	@Value
	@EqualsAndHashCode(callSuper = true)
	public static class RsPaintCanvasRequest extends PartyMemberMessage
	{
	}
}

package com.rspaint;

import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Constants;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(RsPaintConfig.GROUP)
public interface RsPaintConfig extends Config
{
	// Saved strokes, colors and the stroke size are in this group too, so it must not change.
	String GROUP = "rspaint";

	@ConfigItem(
		keyName = "drawKeybind",
		name = "Draw keybind",
		description = "Hold this key and click and drag to draw. If Toggle draw and erase is on, press it to turn draw mode on or off.",
		position = 0
	)
	default Keybind drawKeybind()
	{
		return new Keybind(KeyEvent.VK_B, InputEvent.CTRL_DOWN_MASK);
	}

	@ConfigItem(
		keyName = "eraseKeybind",
		name = "Erase keybind",
		description = "Hold this key and click and drag to erase. If Toggle draw and erase is on, press it to turn erase mode on or off.",
		position = 1
	)
	default Keybind eraseKeybind()
	{
		return new Keybind(KeyEvent.VK_E, InputEvent.CTRL_DOWN_MASK);
	}

	@ConfigItem(
		keyName = "undoKeybind",
		name = "Undo keybind",
		description = "In draw mode or erase mode, press this key to undo your last line or erase.",
		position = 2
	)
	default Keybind undoKeybind()
	{
		return new Keybind(KeyEvent.VK_Z, InputEvent.CTRL_DOWN_MASK);
	}

	@ConfigItem(
		keyName = "redoKeybind",
		name = "Redo keybind",
		description = "In draw mode or erase mode, press this key to redo the last change that you undid.",
		position = 3
	)
	default Keybind redoKeybind()
	{
		return new Keybind(KeyEvent.VK_Z, InputEvent.CTRL_DOWN_MASK | InputEvent.SHIFT_DOWN_MASK);
	}

	@ConfigItem(
		keyName = "toggleModes",
		name = "Toggle draw and erase",
		description = "Press the draw or erase key once to turn the mode on, and again to turn it off, instead of holding the key.",
		position = 4
	)
	default boolean toggleModes()
	{
		return true;
	}

	@ConfigSection(
		name = "Rendering",
		description = "These settings change only how strokes look on your screen. They do not change the strokes that party members get.",
		position = 5
	)
	String renderingSection = "rendering";

	@ConfigItem(
		keyName = "lineStyle",
		name = "Line style",
		description = "Straight connects the points with straight lines. Smooth draws curves near the points and hides small steps. Smooth through points draws curves that touch each point.",
		section = renderingSection,
		position = 0
	)
	default LineStyle lineStyle()
	{
		return LineStyle.STRAIGHT;
	}

	@ConfigItem(
		keyName = "antialiasing",
		name = "Smooth edges",
		description = "Draws strokes with antialiasing (soft line edges).",
		section = renderingSection,
		position = 1
	)
	default boolean antialiasing()
	{
		return true;
	}

	@ConfigItem(
		keyName = "scaleWidthWithZoom",
		name = "Scale width with zoom",
		description = "Makes strokes wider when you zoom in and thinner when you zoom out, so that they keep their size on the ground. The stroke size on the toolbar is the width at the default zoom in fixed mode.",
		section = renderingSection,
		position = 2
	)
	default boolean scaleWidthWithZoom()
	{
		return true;
	}

	@ConfigItem(
		keyName = "transparentStrokes",
		name = "Transparent strokes",
		description = "Lets the game show through strokes that have a transparent color, and through all strokes if Stroke opacity is less than 100%. Where a stroke crosses itself, it does not get darker. Where a stroke crosses an older stroke, the colors mix. If this is off, all strokes are opaque.",
		section = renderingSection,
		position = 3
	)
	default boolean transparentStrokes()
	{
		return true;
	}

	@Range(min = 10, max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "strokeOpacity",
		name = "Stroke opacity",
		description = "Changes the opacity of all strokes, if Transparent strokes is on. It multiplies the opacity of each stroke color. At 100%, each stroke keeps the opacity of its color.",
		section = renderingSection,
		position = 4
	)
	default int strokeOpacity()
	{
		return 100;
	}

	@Range(min = 0, max = Constants.EXTENDED_SCENE_SIZE)
	@ConfigItem(
		keyName = "renderDistance",
		name = "Render distance",
		description = "Strokes show only on tiles that are up to this many tiles from the camera, like Draw Distance in the GPU plugin. At 0, strokes show on all loaded tiles.",
		section = renderingSection,
		position = 5
	)
	default int renderDistance()
	{
		return 0;
	}

	/** How a stroke connects its points on the screen. It changes only the drawing, not the stored points. */
	@RequiredArgsConstructor
	enum LineStyle
	{
		STRAIGHT("Straight"),
		SMOOTH("Smooth"),
		THROUGH_POINTS("Smooth through points");

		private final String displayName;

		@Override
		public String toString()
		{
			return displayName;
		}
	}
}

