import net.runelite.client.util.Filepath;

@PluginDescriptor(
	name = "RsPaint",
	description = "Draw on the ground.",
	tags = {"paint", "draw", "ground", "marker", "tile", "color", "art"},
	internalName = "rspaint"
)
public class RsPaintPlugin extends Plugin
{
	@Provides RsPaintConfig provideConfig(ConfigManager configManager) { return configManager.getConfig(RsPaintConfig.class); }
	@Inject KeyManager keyManager;
	@Inject MouseManager mouseManager;
	@Inject BGMIOverlay bgmiOverlay;
	@Inject EventBus eventBus;
	@Inject OverlayManager overlayManager;
	@Inject PartyCanvasSync partySync;
	@Inject RsPaintPanel panel;
	@Inject ClientToolbar clientToolbar;

	private NavigationButton navigationButton;

	/** Returns the data folder of the plugin, .runelite/plugin-data/rspaint. Do not call it on the client thread. */
	Filepath dataDirectory() throws IOException
	{
		return getPluginDirectory();
	}

	@Override
	protected void startUp() throws Exception
	{
		bgmiOverlay.startUp();
		overlayManager.add(bgmiOverlay);
		mouseManager.registerMouseListener(bgmiOverlay);
		keyManager.registerKeyListener(bgmiOverlay);
		eventBus.register(bgmiOverlay);

		partySync.startUp();
		eventBus.register(partySync);

		eventBus.register(panel);
		navigationButton = NavigationButton.builder()
			.tooltip("RsPaint")
			.icon(RsPaintPanel.createIcon())
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navigationButton);
		panel.refresh();
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(bgmiOverlay);
		mouseManager.unregisterMouseListener(bgmiOverlay);
		keyManager.unregisterKeyListener(bgmiOverlay);
		eventBus.unregister(bgmiOverlay);
		bgmiOverlay.shutDown();

		eventBus.unregister(partySync);
		partySync.shutDown();

		// All members show again on the next start, so the panel must rebuild its switches.
		eventBus.unregister(panel);
		panel.reset();
		clientToolbar.removeNavigation(navigationButton);
	}

	@Value
	static class StrokePoint {
		int x, y;
		float subx, suby;
	}

	static class Stroke {
		// The stored width is in screen pixels. If "Scale width with zoom" is on, the overlay changes it with the zoom.
		static final int MIN_WIDTH = 1;
		static final int MAX_WIDTH = 100;

		/** Returns the width, or 1 if the width is not a number from MIN_WIDTH to MAX_WIDTH. */
		static double validWidth(double width)
		{
			return width >= MIN_WIDTH && width <= MAX_WIDTH ? width : 1;
		}

		static boolean isValidPlane(int plane)
		{
			return plane >= 0 && plane < Constants.MAX_Z;
		}

		/** From the stroke that draws first, at the bottom, to the stroke that draws last, on top. */
		static final Comparator<Stroke> DRAW_ORDER = Comparator.comparingLong((Stroke s) -> s.order).thenComparing(s -> s.id);

		// A random 63-bit number in base 36. It is shorter than a UUID, and only one member's strokes must not collide.
		// Strokes saved before ids existed get a new id when they load.
		String id = Long.toString(ThreadLocalRandom.current().nextLong() & Long.MAX_VALUE, Character.MAX_RADIX);
		List<StrokePoint> pts = new ArrayList<>();
		Color color;
		double strokeWidth;
		// The draw order from StrokeClock. It is 0 for strokes saved before the draw order existed.
		long order;
		// The plane (floor) that the stroke was drawn on. The stroke shows only while the player is on this plane.
		// Strokes saved before the plane existed load on plane 0.
		int plane;
		// The color without its opacity. Made when first needed, so drawing does not make a new Color on each frame.
		// Transient, so it is not saved with the stroke.
		private transient Color opaqueColor;

		/** Returns the color with full opacity. The color of a stroke does not change after the stroke is made. */
		Color opaqueColor()
		{
			if (opaqueColor == null)
			{
				opaqueColor = color.getAlpha() == 255 ? color : new Color(color.getRGB(), false);
			}
			return opaqueColor;
		}

		public int primaryRegion()
		{
			return new WorldPoint(pts.get(0).getX(), pts.get(0).getY(), 0).getRegionID();
		}
	}

	/**
	 * Gives each stroke a draw order. A stroke with a higher order draws over a stroke with a lower order.
	 *
	 * <p>The order of a new stroke is the current time in milliseconds, but always higher than the order of
	 * all strokes that this client already has. Thus a new stroke draws over all strokes that the player can see,
	 * also when the clocks of party members are not the same. Party members send the order with each stroke,
	 * so all clients draw the strokes in the same order.
	 *
	 * <p>Client thread only.
	 */
	@Singleton
	static class StrokeClock
	{
		// Larger orders are not accepted from party members, so a bad value cannot make the clock overflow.
		private static final long MAX_ORDER = 1L << 53;

		private long last = 0;

		/** Returns the order for a new stroke. */
		long next()
		{
			last = Math.max(last + 1, System.currentTimeMillis());
			return last;
		}

		/**
		 * Returns the order to use for a stroke from a party member, and moves the clock past it.
		 * If the order is not valid, for example because the member has an old version of the plugin, returns a new order.
		 */
		long receive(long order)
		{
			if (order <= 0 || order >= MAX_ORDER)
			{
				return next();
			}
			last = Math.max(last, order);
			return order;
		}

		/**
		 * Moves the clock past the order of a saved stroke, so new strokes draw over it. A saved order can be in the future,
		 * for example because a party member with a fast clock moved the clock forward in an earlier session.
		 * Orders that are not valid do not change the clock, and the stroke keeps its order.
		 */
		void advancePast(long order)
		{
			if (order > 0 && order < MAX_ORDER)
			{
				last = Math.max(last, order);
			}
		}
	}
}

package com.rspaint;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.FileAlreadyExistsException;
import java.nio.file.StandardOpenOption;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Saves saved text in an old format to a file before the overlay saves it again in the current format.
 * The files are in .runelite/plugin-data/rspaint/backups. The player can import a file through the panel.
 */
@Slf4j
@Singleton
class StrokeBackups
{
	static final String DIRECTORY = "backups";

	private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss");

	// The most files with the same name and time. Real backups never get near this.
	private static final int MAX_ATTEMPTS = 100;

	private final RsPaintPlugin plugin;
	private final ScheduledExecutorService executor;

	@Inject
	StrokeBackups(RsPaintPlugin plugin, ScheduledExecutorService executor)
	{
		this.plugin = plugin;
		this.executor = executor;
	}

	/**
	 * Writes the text to a new file on a background thread. The future fails if the file cannot be written.
	 *
	 * @param key the config key of the text, for example strokes_12850
	 * @param version the format version of the text
	 */
	CompletableFuture<Void> save(String key, int version, String text)
	{
		String time = LocalDateTime.now().format(TIME);
		return CompletableFuture.runAsync(() ->
		{
			try
			{
				Filepath file = write(key, version, time, text);
				log.debug("Saved a backup of {} (format {}) to {}", key, version, file);
			}
			catch (IOException e)
			{
				throw new UncheckedIOException(e);
			}
		}, executor);
	}

	private Filepath write(String key, int version, String time, String text) throws IOException
	{
		Filepath directory = plugin.dataDirectory().joinSegment(DIRECTORY);
		directory.createDirectories();
		for (int attempt = 1; attempt <= MAX_ATTEMPTS; attempt++)
		{
			Filepath file = directory.joinSegment(fileName(key, version, time, attempt));
			try
			{
				// Never write over an older backup.
				file.write(text, StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE);
				return file;
			}
			catch (FileAlreadyExistsException e)
			{
				// Try the next name.
			}
		}
		throw new IOException("All backup names for " + key + " at " + time + " are in use.");
	}

	/** Returns the file name, for example strokes_12850_format1_20261109-153012.json. Attempts after the first get a number. */
	static String fileName(String key, int version, String time, int attempt)
	{
		String suffix = attempt <= 1 ? "" : "_" + attempt;
		return key + "_format" + version + "_" + time + suffix + ".json";
	}
}

package com.rspaint;

import com.google.gson.TypeAdapter;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import com.google.gson.stream.JsonWriter;
import com.rspaint.RsPaintPlugin.StrokePoint;
import java.awt.geom.Line2D;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Base64;
import java.util.Deque;
import java.util.List;

/**
 * Writes the points of a stroke as one short string, for party messages, exports and saved strokes.
 * Also removes the points of a complete stroke that do not change its shape.
 *
 * <p>Each position is rounded to 1/128 of a tile, which is one local unit. The first point is stored as its full
 * position, and each other point as the change from the point before it. Consecutive points are near each other,
 * so most changes fit in one byte (zigzag varint). The bytes are base64 with the URL alphabet and no padding,
 * so that Gson does not escape them.
 */
final class StrokeCodec
{
	static final int UNITS_PER_TILE = 128;

	// Simplify removes a point if it is at most this many local units from the line between the kept points around it.
	// 2 units is 1/64 of a tile: about half a pixel at the default zoom, and about 2 pixels at full zoom.
	private static final double SIMPLIFY_TOLERANCE = 2;

	// A change has at most 5 varint bytes. That is more than the int range of a position needs.
	private static final int MAX_VARINT_BYTES = 5;

	private StrokeCodec()
	{
	}

	static String encode(List<StrokePoint> points)
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream(points.size() * 2 + 8);
		long lastX = 0;
		long lastY = 0;
		for (StrokePoint point : points)
		{
			long x = toUnits(point.getX(), point.getSubx());
			long y = toUnits(point.getY(), point.getSuby());
			writeVarint(out, zigzag(x - lastX));
			writeVarint(out, zigzag(y - lastY));
			lastX = x;
			lastY = y;
		}
		return Base64.getUrlEncoder().withoutPadding().encodeToString(out.toByteArray());
	}

	/**
	 * Returns the points without the ones that are nearly on the line between their neighbors (Ramer-Douglas-Peucker).
	 * The kept points are rounded to 1/128 tile, as encode rounds them, so you and your party have the same points.
	 */
	static List<StrokePoint> simplify(List<StrokePoint> points)
	{
		int n = points.size();
		long[] xs = new long[n];
		long[] ys = new long[n];
		for (int i = 0; i < n; i++)
		{
			StrokePoint point = points.get(i);
			xs[i] = toUnits(point.getX(), point.getSubx());
			ys[i] = toUnits(point.getY(), point.getSuby());
		}

		boolean[] keep = new boolean[n];
		if (n > 0)
		{
			keep[0] = true;
			keep[n - 1] = true;
		}

		// A stack of index ranges, not recursion, so a very long stroke cannot overflow the call stack.
		double toleranceSq = SIMPLIFY_TOLERANCE * SIMPLIFY_TOLERANCE;
		Deque<int[]> ranges = new ArrayDeque<>();
		if (n > 2)
		{
			ranges.push(new int[]{0, n - 1});
		}
		while (!ranges.isEmpty())
		{
			int[] range = ranges.pop();
			int first = range[0];
			int last = range[1];
			int farthest = -1;
			double farthestSq = toleranceSq;
			for (int i = first + 1; i < last; i++)
			{
				double distanceSq = Line2D.ptSegDistSq(xs[first], ys[first], xs[last], ys[last], xs[i], ys[i]);
				if (distanceSq > farthestSq)
				{
					farthestSq = distanceSq;
					farthest = i;
				}
			}
			if (farthest != -1)
			{
				keep[farthest] = true;
				ranges.push(new int[]{first, farthest});
				ranges.push(new int[]{farthest, last});
			}
		}

		List<StrokePoint> result = new ArrayList<>();
		for (int i = 0; i < n; i++)
		{
			if (keep[i])
			{
				result.add(fromUnits(xs[i], ys[i]));
			}
		}
		return result;
	}

	/** Returns the points, or null if the string is not a valid encoding. */
	static List<StrokePoint> decode(String encoded)
	{
		byte[] bytes;
		try
		{
			bytes = Base64.getUrlDecoder().decode(encoded);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}

		List<StrokePoint> points = new ArrayList<>();
		int[] position = {0};
		long x = 0;
		long y = 0;
		while (position[0] < bytes.length)
		{
			long dx = readVarint(bytes, position);
			long dy = readVarint(bytes, position);
			if (dx < 0 || dy < 0)
			{
				return null;
			}
			x += unzigzag(dx);
			y += unzigzag(dy);
			if (!fitsInTiles(x) || !fitsInTiles(y))
			{
				return null;
			}
			points.add(fromUnits(x, y));
		}
		return points;
	}

	private static long toUnits(int tile, float sub)
	{
		// Math.round of NaN is 0, so a bad sub-tile position cannot break the encoding.
		float clamped = Math.max(0f, Math.min(1f, sub));
		return (long) tile * UNITS_PER_TILE + Math.round(clamped * UNITS_PER_TILE);
	}

	private static boolean fitsInTiles(long units)
	{
		long tile = Math.floorDiv(units, UNITS_PER_TILE);
		return tile >= Integer.MIN_VALUE && tile <= Integer.MAX_VALUE;
	}

	/** A position at the right or top edge of a tile becomes the left or bottom edge of the next tile. That is the same place. */
	private static StrokePoint fromUnits(long x, long y)
	{
		return new StrokePoint(
			(int) Math.floorDiv(x, UNITS_PER_TILE),
			(int) Math.floorDiv(y, UNITS_PER_TILE),
			Math.floorMod(x, UNITS_PER_TILE) / (float) UNITS_PER_TILE,
			Math.floorMod(y, UNITS_PER_TILE) / (float) UNITS_PER_TILE);
	}

	private static long zigzag(long value)
	{
		return (value << 1) ^ (value >> 63);
	}

	private static long unzigzag(long value)
	{
		return (value >>> 1) ^ -(value & 1);
	}

	private static void writeVarint(ByteArrayOutputStream out, long value)
	{
		while ((value & ~0x7FL) != 0)
		{
			out.write((int) ((value & 0x7F) | 0x80));
			value >>>= 7;
		}
		out.write((int) value);
	}

	/** Returns the value and moves the position past it, or returns -1 if the bytes end or the value is too long. */
	private static long readVarint(byte[] bytes, int[] position)
	{
		long value = 0;
		for (int i = 0; i < MAX_VARINT_BYTES; i++)
		{
			if (position[0] >= bytes.length)
			{
				return -1;
			}
			int b = bytes[position[0]++];
			value |= (long) (b & 0x7F) << (7 * i);
			if ((b & 0x80) == 0)
			{
				return value;
			}
		}
		return -1;
	}

	/** Reads and writes a point list with StrokeCodec. A bad string reads as null, so the stroke is skipped. */
	static final class PointsAdapter extends TypeAdapter<List<StrokePoint>>
	{
		@Override
		public void write(JsonWriter out, List<StrokePoint> points) throws IOException
		{
			if (points == null)
			{
				out.nullValue();
			}
			else
			{
				out.value(encode(points));
			}
		}

		@Override
		public List<StrokePoint> read(JsonReader in) throws IOException
		{
			if (in.peek() != JsonToken.STRING)
			{
				in.skipValue();
				return null;
			}
			return decode(in.nextString());
		}
	}
}

package com.rspaint;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.rspaint.PartyCanvasSync.SyncedStroke;
import com.rspaint.RsPaintPlugin.Stroke;
import com.rspaint.RsPaintPlugin.StrokePoint;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;

/**
 * Turns strokes into JSON text and back. The saved strokes of a region (the config key strokes_[region id]) and the
 * exports through the clipboard use the same text and the same format version.
 *
 * <p>read() finds the version of the text and reads it with the parser of that version. To change the format, raise
 * FORMAT_VERSION, keep the parser of each old version, and add the new version to read().
 */
@Singleton
class StrokeStorage
{
	/**
	 * The format of the text.
	 * Version 1: the format of the original plugin. A plain JSON array of Stroke objects. Each point is a JSON object
	 * with x, y, subx and suby, and the color is a Color object. The strokes have no id, draw order or plane.
	 * Version 2: {"version":2,"strokes":[...]}. Each stroke is a SyncedStroke: an id, an ARGB color, a width,
	 * a draw order, a plane, and the points as one StrokeCodec string.
	 */
	static final int FORMAT_VERSION = 2;

	// The longest text that read() accepts. Real text is much shorter.
	private static final int MAX_TEXT_LENGTH = 32 * 1024 * 1024;

	private final Gson gson;

	@Inject
	StrokeStorage(Gson gson)
	{
		this.gson = gson;
	}

	/**
	 * The text cannot be read. The message is for the player.
	 * The overlay must not save over saved text that it cannot read, so the strokes are not lost.
	 */
	static class UnreadableStrokesException extends Exception
	{
		UnreadableStrokesException(String message)
		{
			super(message);
		}

		UnreadableStrokesException(String message, Throwable cause)
		{
			super(message, cause);
		}
	}

	/** The strokes of the text in the current format, and the format version that the text had. */
	@Value
	static class Loaded
	{
		int version;
		List<SyncedStroke> strokes;
	}

	@Value
	private static class Saved
	{
		int version;
		List<SyncedStroke> strokes;
	}

	/** Returns the strokes as text in the current format, sorted in draw order. */
	String write(List<SyncedStroke> strokes)
	{
		List<SyncedStroke> sorted = new ArrayList<>(strokes);
		sorted.sort(SyncedStroke.DRAW_ORDER);
		return gson.toJson(new Saved(FORMAT_VERSION, sorted));
	}

	/** Returns the valid strokes of the text in the current format, in the order of the text. Bad strokes are skipped. */
	Loaded read(String text) throws UnreadableStrokesException
	{
		if (text.length() > MAX_TEXT_LENGTH)
		{
			throw new UnreadableStrokesException("The text is too long.");
		}

		int version;
		List<SyncedStroke> strokes;
		try
		{
			JsonElement root = gson.fromJson(text, JsonElement.class);
			if (root != null && root.isJsonArray())
			{
				version = 1;
				strokes = readVersion1(root);
			}
			else if (root != null && root.isJsonObject())
			{
				version = formatVersion(root.getAsJsonObject());
				JsonElement list = root.getAsJsonObject().get("strokes");
				if (list == null || !list.isJsonArray())
				{
					throw new UnreadableStrokesException("The text has no stroke list.");
				}
				// Builds of this branch before version 2 saved version 1 strokes in {"version":1,"strokes":[...]}.
				strokes = version == 1 ? readVersion1(list) : Arrays.asList(gson.fromJson(list, SyncedStroke[].class));
			}
			else
			{
				throw new UnreadableStrokesException("The text is not drawing JSON.");
			}
		}
		catch (JsonParseException | IllegalStateException | NumberFormatException e)
		{
			throw new UnreadableStrokesException("The text is not valid drawing JSON.", e);
		}

		List<SyncedStroke> result = new ArrayList<>();
		for (SyncedStroke stroke : strokes)
		{
			SyncedStroke clean = clean(stroke);
			if (clean != null)
			{
				result.add(clean);
			}
		}
		return new Loaded(version, result);
	}

	private static int formatVersion(JsonObject root) throws UnreadableStrokesException
	{
		JsonElement version = root.get("version");
		if (version == null || !version.isJsonPrimitive() || !version.getAsJsonPrimitive().isNumber() || version.getAsInt() < 1)
		{
			throw new UnreadableStrokesException("The text has no valid format version.");
		}
		if (version.getAsInt() > FORMAT_VERSION)
		{
			throw new UnreadableStrokesException("A newer version of the plugin made this text (format "
				+ version.getAsInt() + "). Update the plugin.");
		}
		return version.getAsInt();
	}

	/**
	 * Reads version 1 strokes into the current format. A stroke without a draw order gets the position in the list,
	 * so the strokes keep their order under all newer strokes. A stroke without a plane is on plane 0.
	 * The points are simplified, as the overlay does with a new stroke, so the strokes save smaller.
	 */
	private List<SyncedStroke> readVersion1(JsonElement list)
	{
		Stroke[] strokes = gson.fromJson(list, Stroke[].class);
		List<SyncedStroke> result = new ArrayList<>();
		for (int i = 0; i < strokes.length; i++)
		{
			Stroke stroke = strokes[i];
			if (stroke == null || stroke.color == null || stroke.pts == null || stroke.pts.isEmpty() || stroke.pts.contains(null))
			{
				continue;
			}
			if (stroke.order <= 0)
			{
				stroke.order = i + 1;
			}
			result.add(PartyCanvasSync.toSynced(stroke, StrokeCodec.simplify(stroke.pts)));
		}
		return result;
	}

	/** Returns the stroke with valid values, or null if it has no valid points or plane. */
	private static SyncedStroke clean(SyncedStroke stroke)
	{
		if (stroke == null || stroke.getPoints() == null || !Stroke.isValidPlane(stroke.getPlane()))
		{
			return null;
		}

		List<StrokePoint> points = new ArrayList<>();
		for (StrokePoint point : stroke.getPoints())
		{
			if (point != null && Float.isFinite(point.getSubx()) && Float.isFinite(point.getSuby()))
			{
				points.add(new StrokePoint(point.getX(), point.getY(), clamp01(point.getSubx()), clamp01(point.getSuby())));
			}
		}
		if (points.isEmpty())
		{
			return null;
		}

		double width = Stroke.validWidth(stroke.getStrokeWidth());
		return new SyncedStroke(stroke.getId(), stroke.getColor(), width, stroke.getOrder(), stroke.getPlane(), points);
	}

	private static float clamp01(float value)
	{
		return Math.max(0f, Math.min(1f, value));
	}
}

